{
  "components": [
    {
      "type": "claim",
      "quote": "At its meeting on 29 March, it decided, based on the lessons learned from the COVID-19 pandemic, to strengthen the organisation of the Federal Administration so it is better equipped for future crises.",
      "gist": "The Federal Administration will be strengthened based on COVID-19 lessons to handle future crises better."
    },
    {
      "type": "claim",
      "quote": "In the event of complex crises, the Federal Council will be able to deploy crisis units at both a strategic and operational level.",
      "gist": "The Federal Council can deploy crisis units at strategic and operational levels during complex crises."
    },
    {
      "type": "claim",
      "quote": "The Federal Council remains the supreme governing authority.",
      "gist": "The Federal Council is confirmed as the supreme governing authority."
    },
    {
      "type": "claim",
      "quote": "In addition, a Standing Core Unit will provide crisis management support to the departmental staff offices.",
      "gist": "A Standing Core Unit will support departmental staff offices with crisis management."
    }
  ]
}
